static G_V: &[u8] = &[209, 4, 128, 0, 18];

pub struct ArmenianStemmer {
    e: Env,
    I_p2: i32,
    I_pV: i32,
}

impl ArmenianStemmer {
    fn new(word: &str) -> Self {
        ArmenianStemmer { e: Env::new(word), I_p2: 0, I_pV: 0 }
    }
    fn r_mark_regions(&mut self) -> bool {
        self.I_pV = self.e.limit;
        self.I_p2 = self.e.limit;
        let mut v_1: i32 = self.e.cursor;
        'lab0: {
            'golab1: loop {
                'lab2: {
                    if !(self.e.in_grouping(G_V, 1377, 1413)) {
                        break 'lab2;
                    }
                    break 'golab1;
                }
                if self.e.cursor >= self.e.limit {
                    break 'lab0;
                }
                self.e.cursor += 1;
            }
            self.I_pV = self.e.cursor;
            'golab3: loop {
                'lab4: {
                    if !(self.e.out_grouping(G_V, 1377, 1413)) {
                        break 'lab4;
                    }
                    break 'golab3;
                }
                if self.e.cursor >= self.e.limit {
                    break 'lab0;
                }
                self.e.cursor += 1;
            }
            'golab5: loop {
                'lab6: {
                    if !(self.e.in_grouping(G_V, 1377, 1413)) {
                        break 'lab6;
                    }
                    break 'golab5;
                }
                if self.e.cursor >= self.e.limit {
                    break 'lab0;
                }
                self.e.cursor += 1;
            }
            'golab7: loop {
                'lab8: {
                    if !(self.e.out_grouping(G_V, 1377, 1413)) {
                        break 'lab8;
                    }
                    break 'golab7;
                }
                if self.e.cursor >= self.e.limit {
                    break 'lab0;
                }
                self.e.cursor += 1;
            }
            self.I_p2 = self.e.cursor;
        }
        self.e.cursor = v_1;
        return true;
    }
    fn r_R2(&mut self) -> bool {
        return self.I_p2 <= self.e.cursor;
    }
    fn r_adjective(&mut self) -> bool {
        self.e.ket = self.e.cursor;
        if self.e.find_among_b(A_0) == 0 {
            return false;
        }
        self.e.bra = self.e.cursor;
        self.e.slice_del();
        return true;
    }
    fn r_verb(&mut self) -> bool {
        self.e.ket = self.e.cursor;
        if self.e.find_among_b(A_1) == 0 {
            return false;
        }
        self.e.bra = self.e.cursor;
        self.e.slice_del();
        return true;
    }
    fn r_noun(&mut self) -> bool {
        self.e.ket = self.e.cursor;
        if self.e.find_among_b(A_2) == 0 {
            return false;
        }
        self.e.bra = self.e.cursor;
        self.e.slice_del();
        return true;
    }
    fn r_ending(&mut self) -> bool {
        self.e.ket = self.e.cursor;
        if self.e.find_among_b(A_3) == 0 {
            return false;
        }
        self.e.bra = self.e.cursor;
        if !self.r_R2() {
            return false;
        }
        self.e.slice_del();
        return true;
    }
    pub fn stem(&mut self) -> bool {
        self.r_mark_regions();
        self.e.limit_backward = self.e.cursor;
        self.e.cursor = self.e.limit;
        if self.e.cursor < self.I_pV {
            return false;
        }
        let mut v_3: i32 = self.e.limit_backward;
        self.e.limit_backward = self.I_pV;
        let mut v_4: i32 = self.e.limit - self.e.cursor;
        self.r_ending();
        self.e.cursor = self.e.limit - v_4;
        let mut v_5: i32 = self.e.limit - self.e.cursor;
        self.r_verb();
        self.e.cursor = self.e.limit - v_5;
        let mut v_6: i32 = self.e.limit - self.e.cursor;
        self.r_adjective();
        self.e.cursor = self.e.limit - v_6;
        let mut v_7: i32 = self.e.limit - self.e.cursor;
        self.r_noun();
        self.e.cursor = self.e.limit - v_7;
        self.e.limit_backward = v_3;
        self.e.cursor = self.e.limit_backward;
        return true;
    }
}

/// Stem one (lowercased) word.
pub fn stem(word: &str) -> String {
    let mut s = ArmenianStemmer::new(word);
    s.stem();
    s.e.current()
}
